// Helper functions
export function getIndustriesByUrl(url: string): PageData | undefined {
  const cleanUrl = url.replace(/^\/+|\/+$/g, '');
  return industriesData.pages.find(page => 
    page.url === url || 
    page.url === `/${url}` ||
    page.url.replace(/^\/+|\/+$/g, '') === cleanUrl
  );
}

export function getIndustriesByKeyword(keyword: string): PageData[] {
  return industriesData.pages.filter(page =>
    page.metadata.primaryKeyword === keyword ||
    page.metadata.secondaryKeywords.includes(keyword)
  );
}

export default industriesData;
